def forward(groups):
    bufstart = int(groups[0])
    return {'stored': [bufstart], 'layout': [groups[1], groups[2]]}

def inverse(record):
    bufstart = record['stored'][0]
    bufend, bufvoid = record['layout']
    return f"bufstart = {bufstart}; bufend = {bufend}; bufvoid = {bufvoid}"
